  if (err.code !== 'ENOENT') throw err;
}

if (config.port === undefined) config.port = 3000;
if (config.host === undefined) config.host = '127.0.0.1';

fs.writeFileSync(outPath, JSON.stringify(config, null, 2) + '\n');
console.log(`Wrote ${outPath}`);

